Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```c++
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    std::string wordToSearch; // Wort, nach dem gesucht werden soll
    std::cout << "Enter the word to search: ";
    std::cin >> wordToSearch;

    std::string fileName;
    std::cout << "Enter the file name: ";
    std::cin >> fileName;

    std::ifstream file(fileName); // Öffnen der Datei
    if (!file) {
        std::cerr << "Could not open file: " << fileName << std::endl;
        return 1;
    }

    std::vector<std::string> lines; // Vektor für Zeilen der Datei
    std::string line;
    while (getline(file, line)) {
        lines.push_back(line);
    }

    int count = 0; // Anzahl der Vorkommen des Suchworts
    for (const auto& line : lines) {
        std::size_t pos = 0;
        while ((pos = line.find(wordToSearch, pos)) != std::string::npos) {
            ++count;
            pos += wordToSearch.length();
        }
    }

    std::cout << "The word \"" << wordToSearch << "\" appears " << count << " times in " << fileName << "." << std::endl;

    file.close();

    return 0;
}
